select pg_temp.actor('creator');
set constraints all deferred;
create function pg_temp.control_payload(n text default 'control.ap',k text default 'AP',d text default '2026-09-21') returns jsonb language sql as $$select jsonb_build_object('id',pg_temp.fid(n),'kind',k,'as_of',d)$$;
create function pg_temp.control_page(n text,s text,k text default null) returns jsonb language sql as $$select api.control_reconciliation_report_page(pg_temp.fid('tenant'),pg_temp.fid('entity'),pg_temp.fid('branch'),pg_temp.fid(n),s,0,k)$$;
-- A later backdated bill belongs only to a new report; the saved snapshot is stable.
select pg_temp.call('upsert_supplier_bill',pg_temp.direct_bill('control.later.bill'));
select pg_temp.call('post_supplier_bill',jsonb_build_object('document_id',pg_temp.fid('control.later.bill')),1);
create function pg_temp.fail_control_outbox() returns trigger language plpgsql as $$begin raise exception using errcode='P0001',message='CONTROL_OUTBOX_FAILURE';end $$;
create trigger synthetic_control_failure before insert on core.outbox_events for each row execute function pg_temp.fail_control_outbox();
drop trigger synthetic_control_failure on core.outbox_events;
delete from core.role_permissions where tenant_id=pg_temp.fid('tenant') and role_id=pg_temp.fid('creator.role') and permission_code='finance.controls.reconcile';
select pg_temp.actor('creator','aal1');
select pg_temp.actor('creator');
set local role authenticated;
reset role;
set constraints all immediate;
