insert into core.role_permissions(tenant_id,role_id,permission_code) values(pg_temp.fid('tenant'),pg_temp.fid('creator.role'),'finance.controls.reconcile') on conflict do nothing;
insert into procurement_test_results select throws_ok($$select pg_temp.call('generate_control_reconciliation_report',pg_temp.control_payload('invalid','BAD'),0)$$,'22023','CONTROL_REPORT_INPUT_INVALID','control report rejects invalid ledger kind');
insert into procurement_test_results select throws_ok($$select pg_temp.call('generate_control_reconciliation_report',pg_temp.control_payload(),1)$$,'40001','VERSION_CONFLICT','control snapshot requires version zero');
insert into procurement_responses values('control.ap',pg_temp.call('generate_control_reconciliation_report',pg_temp.control_payload(),0,'control.ap'));
insert into procurement_test_results select is(pg_temp.call('generate_control_reconciliation_report',pg_temp.control_payload(),0,'control.ap'),(select response from procurement_responses where name='control.ap'),'control snapshot replay is exact');
insert into procurement_test_results select is((select (response#>>'{entity,difference}')::numeric from procurement_responses where name='control.ap'),0::numeric,'AP residual carrying value reconciles exactly to credit-positive GL');
insert into procurement_test_results select is((select (response#>>'{entity,difference_count}')::integer from procurement_responses where name='control.ap'),0,'AP allocation and FX reversal source commands reconcile individually');
insert into procurement_test_results select is((select sum((x->>'difference')::numeric) from jsonb_array_elements(pg_temp.control_page('control.ap','accounts')->'items')x),0::numeric,'AP control accounts reconcile independently');
insert into procurement_test_results select throws_ok($$delete from finance.control_reports where id=pg_temp.fid('control.ap')$$,'55000',null,'saved control evidence is immutable');
insert into procurement_test_results select throws_ok($$select pg_temp.control_page('control.ap',null)$$,'22023','CONTROL_REPORT_PAGE_INVALID','null evidence section rejected');
insert into procurement_test_results select throws_ok($$select api.control_reconciliation_report_page(pg_temp.fid('tenant'),pg_temp.fid('entity'),pg_temp.fid('trace.hiddenbranch'),pg_temp.fid('control.ap'),'items')$$,'42501',null,'report from another branch cannot be opened');
insert into procurement_responses values('control.items.before',pg_temp.control_page('control.ap','items'));
insert into procurement_test_results select is(pg_temp.control_page('control.ap','items'),(select response from procurement_responses where name='control.items.before'),'later backdated AP posting cannot change saved report');
insert into procurement_responses values('control.ap.new',pg_temp.call('generate_control_reconciliation_report',pg_temp.control_payload('control.ap.new'),0));
insert into procurement_test_results select is((select (response#>>'{entity,item_count}')::integer from procurement_responses where name='control.ap.new'),(select (response#>>'{entity,item_count}')::integer+1 from procurement_responses where name='control.ap'),'fresh report includes newly posted item');
insert into procurement_test_results select throws_ok($$select pg_temp.call('generate_control_reconciliation_report',pg_temp.control_payload('control.failed'),0)$$,'P0001','CONTROL_OUTBOX_FAILURE','late report failure rolls back evidence and receipt');
insert into procurement_test_results select is((select count(*) from finance.control_reports where id=pg_temp.fid('control.failed')),0::bigint,'failed report leaves no saved snapshot');
insert into procurement_test_results select throws_ok($$select pg_temp.control_page('control.ap','items')$$,'42501',null,'revocation denies saved private evidence');
insert into procurement_test_results select throws_ok($$select pg_temp.call('generate_control_reconciliation_report',pg_temp.control_payload(),0,'control.ap')$$,'42501',null,'replay rechecks current reconciliation access');
insert into core.role_permissions(tenant_id,role_id,permission_code) values(pg_temp.fid('tenant'),pg_temp.fid('creator.role'),'finance.controls.reconcile');
insert into procurement_test_results select throws_ok($$select pg_temp.control_page('control.ap','journals')$$,'42501',null,'privileged reconciliation honors existing MFA policy');
insert into procurement_test_results select throws_ok($$select * from finance.control_reports$$,'42501',null,'direct private reconciliation table reads denied');
